  +pub(crate) const OSC52_MAX_BYTES: usize = 74_994;
  +
  +/// Whether the OSC 52 clipboard write is wanted: on unless `NEXUS_OSC52` is `off` (also `0`, `false`, `no`, `none`).
  +pub(crate) fn osc52_enabled(value: Option<&str>) -> bool {
