      assert.doesNotMatch(projected.clipboard, /\x1b/, "the boundary makes control characters visible before the TUI sees them");
    } finally {
      app.shutdown();
      if (previousHome === undefined) delete process.env.HOME;
      else process.env.HOME = previousHome;
